SELECT typeof(capacity_slot) AS slot_class, CAST(capacity_slot AS TEXT) AS capacity_slot, item_id, record, stream, typeof(seq) AS seq_class, CAST(seq AS TEXT) AS seq, typeof(live) AS live_class, CAST(live AS TEXT) AS live, typeof(payload_bytes) AS payload_class, CAST(payload_bytes AS TEXT) AS payload_bytes, typeof(settlement_bytes) AS settlement_class, CAST(settlement_bytes AS TEXT) AS settlement_bytes FROM _fleet_sync_mail_items WHERE live = 1 AND json_extract(record, '$.value.fetched') = 0 ORDER BY json_extract(record, '$.value.payload.value.validUntil'), item_id;
